         INSERT INTO PublishEventData 
		 (
		 Id,
		 EventName,
		 OperationType,
		 OperationDateTimeUtc,
		 ApiName,
		 CollectionName,
		 [Data]
		 )
		 OUTPUT
		 Inserted.Id
		 VALUES    
		 (
		 @Id,
		 @EventName,
		 @OperationType,
		 @OperationDateTimeUtc, 
		 @ApiName, 
		 @CollectionName,
		 @Data
		 );
